// The old Jekyll (Chirpy) site registered a service worker at /sw.min.js.
// That worker served pages from its cache. The new site has no service worker.
// When a returning visitor's browser checks /sw.min.js for an update, it gets
// this file: it deletes the old caches, removes itself, and reloads open pages.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) client.navigate(client.url);
    })()
  );
});
